export R="/Users/dm/dev/dev/個人開発/harness/eval-log/dev-graph/live-trial-fixtures/r5-requirements"
cd "$R" && python3 - <<'PY'
import hashlib, json, os
root='.'
g=json.load(open('.dev-graph/state/graph.json'))
def sha(p):
    return hashlib.sha256(open(p,'rb').read()).hexdigest()
for n in g['nodes']:
    sl=n.get('source_lineage') or {}
    sp=sl.get('source_path')
    if sp and os.path.exists(sp):
        print(n['graph_node_id'], sl.get('source_digest')==sha(sp), sl.get('source_digest')[:12], sha(sp)[:12], sp)
    else:
        print(n['graph_node_id'], 'no-source-path', sp)
PY

